  Skill_130946_Desc_1 = {
    Text = "พันธมิตรทั้งหมดได้รับ [Arg1] <PVPWaterPowerKeyWords:วังวน> และ<DelayKeywords:ความหน่วง 1>：[Arg2] อาลีมัส."
