  Skill_145558_Name_1 = {Text = "ตี"},
  Skill_145559_Desc_1 = {
    Text = "สร้าง <Damage:[Damage:Arg1]> <PVPPunctureDamagewords:ดาเมจทะลวง> แก่ศัตรูแถวหน้า, หากสังหารศัตรูใดก็ตาม, ได้รับ [Arg2] <PVPPowerIconKeywords:STR>."
  },
  Skill_145559_Name_1 = {
    Text = "อสูรวาฬหวนคืนสู่ห้วงสมุทร"
  },
  Skill_145560_Desc_1 = {
    Text = "สร้าง <Damage:[Damage:Arg1]> ความเสียหายแก่ศัตรูทั้งหมด, และชั่วคราวแย่งชิง [Arg2] <PVPPowerIconKeywords:STR>, สูญเสีย [Arg3] HP."
  },
  Skill_145560_Name_1 = {
    Text = "คมดาบดับสูญ"
  },
  Skill_145561_Desc_1 = {
    Text = "สร้าง <Damage:[Damage:Arg1]> <PVPPunctureDamagewords:ดาเมจทะลวง> ให้กับร่างตื่นทั้งหมดยกเว้นเป้าหมายฝ่ายเดียวกัน, และทำซ้ำผลนี้ทุกครั้งที่เริ่มต้นรอบถัดไป."
  },
  Skill_145561_Name_1 = {
