  Skill_145673_PropertyNameList = {
    Text = "พลังโจมตี*GrowValue1,$GrowValue2"
  },
  Skill_145674_AwakerSkillBackgroundStory = {
    Text = "「เจ้าได้ยินไหม? เสียงร่ำไห้คร่ำครวญของพวกเขาดังกระหึ่มทุกซอกมุม แต่ไม่มีใครยื่นมือมาปกป้องพวกเขาแม้แต่น้อย.」\n「อย่าคิดว่าอุดหูแล้วจะเพิกเฉยได้ อัศวินผู้ไร้ความสามารถ.」\n「เจ้าได้ประสบมาด้วยตนเอง เจ้าได้เลือกแล้ว.」\n「ในยามที่คลื่นศัตรูถาโถมเข้ามา เจ้าทิ้งเกราะทิ้งอาวุธ ปล่อยให้พวกมันย่ำยีแผ่นดินที่เจ้ารักที่สุด.」"
  },
  Skill_145674_BattleDesc = {
