  Skill_66356_AwakerSkillBackgroundStory = {
    Text = "ชีวิตทุกสิ่ง。\nเธอควบคุมเวลาและอวกาศ โลกแห่งระเบียบไหลออกมาจากปลายนิ้วของเธอ。\nทุกสิ่งรวมเป็นหนึ่ง。\nสสารอนินทรีย์และสารอินทรีย์รวมเป็นหนึ่งในความเคออส สุดท้ายจะกลับสู่สุญญตาในลมหายใจของ「พระองค์」。"
  },
  Skill_66356_Desc_0 = {
